// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 nowTime, uint256 unlockParam, address actor, uint256 amount) public {
        // admissible domain: a realistic execution time, an arbitrary caller, a valid deposit amount
        nowTime = bound(nowTime, 2, 1e18);
        amount = bound(amount, 0, 100 ether);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(unlockParam < nowTime); // param names a moment BEFORE the call time (still a wide, admissible domain)

        vm.warp(nowTime);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockParam);

        // General rule: after Put(t) at time now, the stored unlock time is exactly max(t, now);
        // since t < now here, the reference stores now (never a past time). The mutant stores t < now.
        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= nowTime && storedUnlockTime == nowTime);
    }
}
